def solve(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    output = [[0]*w for _ in range(h)]

    seeds = [(r, c) for r in range(h) for c in range(w) if input_grid[r][c] == 3]

    for (seed_r, seed_c) in sorted(seeds):
        # === TOP 5-HOVERS BAR ===
        # Row seed_r-2, cols seed_c-2 to seed_c+2: all 5s
        for c in range(seed_c-2, seed_c+3):
            if 0 <= seed_r-2 < h and 0 <= c < w:
                output[seed_r-2][c] = 5

        # === FRAME COLUMNS FOR MIDDLE ROWS ===
        # Cols seed_c-2 and seed_c+2, rows seed_r-1 to seed_r+1 get value 2
        for c_frame in [seed_c-2, seed_c+2]:
            for r_frame in range(seed_r-1, seed_r+2):
                if 0 <= r_frame < h and 0 <= c_frame < w:
                    if output[r_frame][c_frame] == 0:
                        output[r_frame][c_frame] = 2

        # === INTERIOR PATTERN AT ROWS seed_r-1 and seed_r ===
        # These rows have pattern: 2(frame), 0, 5/3, 0, 2(frame)
        # Row seed_r-1: 2, 0, 5, 0, 2
        # Row seed_r: 2, 0, 3, 0, 2

        for c in range(seed_c-1, seed_c+2):  # cols c-1, c, c+1
            # Col c-1 (left interior): always 0
            if c == seed_c-1 and 0 <= seed_r-1 < h and seed_c-1 < w:
                output[seed_r-1][c] = 0
            elif c == seed_c-1 and 0 <= seed_r < h and seed_c-1 < w:
                output[seed_r][c] = 0

            # Col c (center): 5 at row r-1, 3 at row r
            if c == seed_c:
                if 0 <= seed_r-1 < h:
                    output[seed_r-1][c] = 5
                if 0 <= seed_r < h:
                    output[seed_r][c] = 3

            # Col c+1 (right interior): always 0
            if c == seed_c+1 and 0 <= seed_r-1 < h and seed_c+1 < w:
                output[seed_r-1][c] = 0
            elif c == seed_c+1 and 0 <= seed_r < h and seed_c+1 < w:
                output[seed_r][c] = 0

        # === INTERIOR ROW seed_r+1 ===
        # Row seed_r+1: 2, 0, 0, 0, 2 (all 0 in interior)
        for c in range(seed_c-1, seed_c+2):
            if 0 <= seed_r+1 < h and c < w:
                output[seed_r+1][c] = 0

        # === BOTTOM 8-HBAR ===
        # Row seed_r+2: frame on sides (value 2), 8s in interior cols

        # Calculate how much to extend frame
        # 5-height bar span: seed_c-2 to seed_c+2 (7 cols total, width+4)
        # But interior 8s span: 3 cols
        # Frame extension: max(0, grid_left_edge - (seed_c-2), (seed_c+2) - grid_right_edge)

        left_frame = seed_c-3
        right_frame = seed_c+3

        # Fill left frame
        for lf in range(left_frame, seed_c-2):
            if 0 <= seed_r+2 < h and lf >= 0:
                output[seed_r+2][lf] = 2

        # Fill 8s (interior 5 cols spanning seed_c-2 to seed_c+2)
        for c in range(seed_c-2, seed_c+3):  # 5 cols
            if 0 <= seed_r+2 < h and c < w:
                output[seed_r+2][c] = 8

        # Fill right frame
        for rf in range(seed_c+3, right_frame+1):
            if 0 <= seed_r+2 < h and rf < w:
                output[seed_r+2][rf] = 2

    return output

