def solve(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    output = [[0]*w for _ in range(h)]

    seeds = [(r, c) for r in range(h) for c in range(w) if input_grid[r][c] == 3]

    for (seed_r, seed_c) in sorted(seeds):
        # === TOP 5-HBAR ===
        # Row seed_r-2, cols seed_c-2 to seed_c+2: all 5s (7 cols, centered on seed)
        for c in range(seed_c-2, seed_c+3):
            if 0 <= seed_r-2 < h and 0 <= c < w:
                output[seed_r-2][c] = 5

        # === FRAME COLUMNS ===
        # Cols seed_c-2 and seed_c+2 for rows seed_r-1 to seed_r+1 get value 2
        for c_frame in [seed_c-2, seed_c+2]:
            for r_frame in range(seed_r-1, seed_r+2):
                if 0 <= r_frame < h and 0 <= c_frame < w:
                    if output[r_frame][c_frame] == 0:
                        output[r_frame][c_frame] = 2

        # === INTERIOR ROWS ===
        # Row seed_r-1: [2], [0], [5], [0], [2] at columns [c-2], [c-1], [c], [c+1], [c+2]
        # Row seed_r:   [2], [0], [3], [0], [2]
        # Row seed_r+1: [2], [0], [0], [0], [2]

        frame_cols = [seed_c-2, seed_c+2]
        interior_cols = [seed_c-1, seed_c, seed_c+1]

        for r in [seed_r-1, seed_r, seed_r+1]:
            # Set frame columns
            for c_frame in frame_cols:
                if 0 <= r < h and 0 <= c_frame < w:
                    if output[r][c_frame] == 0:
                        output[r][c_frame] = 2
            # Set interior columns
            for c_int in interior_cols:
                if 0 <= r < h and 0 <= c_int < w:
                    if r == seed_r-1 and c_int == seed_c:
                        output[r][c_int] = 5
                    elif r == seed_r:
                        output[r][c_int] = 3
                    else:
                        output[r][c_int] = 0

